export const BOARD_BODY = "\n<div id=\"stage\">\n  <div class=\"scene\" id=\"s1\"><div id=\"hookpanel\"></div></div>\n  <div class=\"scene\" id=\"s3\"><div id=\"bg\"></div><div id=\"dots\"></div><div id=\"glow\"></div>\n    <div id=\"card\"><div class=\"hdr\" id=\"cardhdr\"></div><div id=\"els\"></div></div></div>\n  <div id=\"cap\"></div>\n</div>\n";
export const BOARD_SCRIPT = "\n// ===== engine (generic). Data injected: WORDS (array {w,s,e}), CFG (from beats.js) =====\nconst FPS = 30000/1001, clamp=(x)=>Math.max(0,Math.min(1,x)), eo=(p)=>1-Math.pow(1-p,3), eio=(p)=>p<.5?4*p*p*p:1-Math.pow(-2*p+2,3)/2;\nconst N = s => s.toLowerCase().replace(/[₹,]/g,'').replace(/[^a-z0-9&']/g,'');\nfunction at(phrase, word, occ=1){ // time of `word` inside first(occ) match of phrase\n  const P = phrase.split(/\\s+/).map(N), Wn = WORDS.map(x=>N(x.w)); let seen=0;\n  for(let i=0;i+P.length<=Wn.length;i++){ let ok=true; for(let k=0;k<P.length;k++) if(Wn[i+k]!==P[k]){ok=false;break}\n    if(ok && ++seen===occ){ const tw = word? P.indexOf(N(word)) : 0; if(tw<0) throw 'word '+word+' not in '+phrase; return WORDS[i+tw].s; } }\n  throw 'phrase not found: '+phrase;\n}\nfunction hdrHTML(part){return `<span class=\"t\">Solving real consultant cases</span><span class=\"pill-part\">Part ${part}</span><span class=\"brand\">gradnext</span>`}  // R1.17: header back (not on end card)\nlet ELS=[], QW=[];\nfunction build(){\n  CFG.init(at);\n  if(CFG.bgVideo){ document.getElementById('bg').style.display='none'; document.getElementById('dots').style.display='none'; }\n  document.getElementById('cardhdr').innerHTML = hdrHTML(CFG.part);\n  const H = document.getElementById('hookpanel');\n  const qw = CFG.hookQ.split(' ').map(w=>`<span class=\"qw\">${w}</span>`).join(' ');\n  const mbb = (CFG.mbbImg && CFG.mbbImg.startsWith('data:')) ? `<img src=\"${CFG.mbbImg}\" style=\"height:${CFG.mbbH||92}px;mix-blend-mode:multiply\">` :\n    `<span class=\"lg\" style=\"font-family:Georgia,serif\">McKinsey &amp; Company</span><span class=\"sep\"></span>\n    <span class=\"lg\" style=\"font-weight:700;font-size:40px;letter-spacing:1px\">BCG</span><span class=\"sep\"></span>\n    <span class=\"lg\" style=\"font-weight:700;letter-spacing:.5px\">BAIN &amp; COMPANY</span>`;\n  H.innerHTML = `<div class=\"hdr\">${hdrHTML(CFG.part)}</div><div id=\"hookimg\"><img src=\"${CFG.hookImg}\"></div><div id=\"hookq\"><div>${qw}</div></div><div id=\"mbb\">${mbb}</div>`;\n  QW=[...H.querySelectorAll('.qw')];\n  const host = document.getElementById('els');\n  for(const e of CFG.els){\n    const d = document.createElement('div'); d.className='el '+(e.cls||''); d.innerHTML = e.html||'';\n    Object.assign(d.style,{left:(e.x||0)+'px',top:(e.y||0)+'px'}); if(e.w) d.style.width=e.w+'px'; if(e.h) d.style.height=e.h+'px';\n    if(e.z) d.style.zIndex=e.z; host.appendChild(d); e.node=d;\n    e.paths=[...d.querySelectorAll('svg.ic .s')]; e.fills=[...d.querySelectorAll('svg.ic .f')];\n    e.paths.forEach(p=>{p.setAttribute('pathLength','1');p.style.strokeDasharray='1';});\n    e.counts=[...d.querySelectorAll('[data-to]')]; e.bars=[...d.querySelectorAll('[data-bar]')];\n    e.units=[...d.querySelectorAll('.grid > div')]; e.subs=[...d.querySelectorAll('[data-in]')];\n    ELS.push(e);\n  }\n  buildCaptions();\n}\nfunction fmtN(n,f){ const r=Math.round(n); const s=r.toLocaleString('en-IN'); return (f||'{n}').replace('{n}',s); }\nfunction seekEl(e,t){\n  const d=e.node; let op=0, dy=0, dx=0;\n  if(t>=e.in){ const p=clamp((t-e.in)/(e.dur||0.22)); op=eo(p); dy=(e.m==='drop'?-8:8)*(1-eo(p)); if(e.m==='pop'){dy=0} }\n  if(e.out!=null && t>=e.out){ op*=1-clamp((t-e.out)/0.25); }\n  if(e.m==='pop' && t>=e.in){ const p=clamp((t-e.in)/0.22); d.style.transform=`scale(${0.85+0.15*eo(p)})`; }\n  else d.style.transform=`translate(${dx}px,${dy}px)`+(e.rot?` rotate(${e.rot}deg)`:'');\n  if(e.moves){ let x=e.x,y=e.y,w=e.w,h=e.h,fs=null;\n    for(const mv of e.moves){ if(t>=mv.t){ const p=eio(clamp((t-mv.t)/0.3)); x+= (mv.x-x)*p; y+=(mv.y-y)*p; if(mv.w) w+=(mv.w-w)*p; if(mv.h) h+=(mv.h-h)*p; if(mv.fs) fs=e.fs+(mv.fs-e.fs)*p; } }\n    Object.assign(d.style,{left:x+'px',top:y+'px',width:w+'px',height:h+'px'}); if(fs) d.style.fontSize=fs+'px'; }\n  d.style.opacity=op; d.style.display = op<=0.001?'none':'';\n  if(op<=0.001) return;\n  e.paths.forEach(p=>{ const q=clamp((t-e.in)/0.4); p.style.strokeDashoffset=1-eo(q); });\n  e.fills.forEach(f=>{ f.style.opacity=clamp((t-e.in-0.35)/0.2); });\n  e.counts.forEach(c=>{ const t0=+(c.dataset.at||e.in), to=+c.dataset.to, fr=+(c.dataset.from ?? to*0.6); const p=eo(clamp((t-t0)/0.45));\n    c.textContent=fmtN(fr+(to-fr)*p, c.dataset.fmt); });\n  e.bars.forEach(b=>{ const t0=+(b.dataset.at||e.in), du=+(b.dataset.dur||0.5); b.style.transform=`scaleX(${eio(clamp((t-t0)/du))})`; });\n  e.units.forEach((u,i)=>{ const p=clamp((t-e.in-i*(e.step||0.05))/0.12); u.style.opacity=p; u.style.transform=`scale(${0.5+0.5*p})`; });\n  e.subs.forEach(s=>{ const t0=+s.dataset.in; const p=clamp((t-t0)/0.22); s.style.opacity=eo(p); s.style.transform=`translateY(${8*(1-eo(p))}px)`; });\n  if(e.states){ let c=''; for(const s of e.states) if(t>=s.t) c=s.c; d.classList.remove('on','off'); if(c) d.classList.add(c); }\n}\n// ===== captions (M01/M02) =====\nlet PHR=[];\nfunction measure(txt){ const c=measure.c||(measure.c=document.createElement('canvas').getContext('2d')); c.font=\"600 52px 'Avenir Next'\"; return c.measureText(txt).width; }\nfunction buildCaptions(){\n  // 1) clauses at punctuation + scene boundaries; 2) merge 1-word clauses within a sentence; 3) split long clauses evenly.\n  const W=WORDS, maxW=CFG.capMaxW||640, maxN=CFG.capMaxWords||4, fits=a=>a.length<=maxN && measure(a.map(i=>W[i].w).join(' '))+(a.length-1)*13<=maxW;\n  const bounds=[CFG.s1End, CFG.s2End]; let cl=[], cur=[];\n  for(let i=0;i<W.length;i++){\n    if(cur.length && bounds.some(b=>W[cur[cur.length-1]].s<b && W[i].s>=b)) { cl.push({w:cur,end:true}); cur=[]; }\n    cur.push(i);\n    if(/[.?!]$/.test(W[i].w)){ cl.push({w:cur,end:true}); cur=[]; }\n    else if(/[,:;]$/.test(W[i].w)){ cl.push({w:cur,end:false}); cur=[]; }\n  }\n  if(cur.length) cl.push({w:cur,end:true});\n  for(let k=0;k<cl.length;k++){ // merge short clause with next clause of same sentence\n    const c=cl[k], n=cl[k+1];\n    if(c.w.length<=(fits(c.w.concat(n?n.w:[]))?2:1) && !c.end && n){ n.w=c.w.concat(n.w); cl.splice(k,1); k--; }\n    else if(n && !c.end && n.w.length===1 && fits(c.w.concat(n.w))){ c.w=c.w.concat(n.w); c.end=n.end; cl.splice(k+1,1); k--; }\n  }\n  for(const c of cl){\n    if(fits(c.w)){ PHR.push(c.w); continue; }\n    for(let n=2;n<12;n++){ const sz=Math.ceil(c.w.length/n), parts=[];\n      for(let j=0;j<c.w.length;j+=sz) parts.push(c.w.slice(j,j+sz));\n      if(parts[parts.length-1].length===1 && parts.length>1){ const l=parts.pop(); parts[parts.length-1].push(l[0]); }\n      if(parts.every(fits)){ PHR.push(...parts); break; } }\n  }\n}\nfunction seekCap(t, mode){\n  const cap=document.getElementById('cap'); const W=WORDS;\n  cap.className = ''; cap.style.top = mode==='s1' ? (CFG.s1CapTop||600)+'px' : '770px';\n  if(mode==='none'){cap.innerHTML='';return}\n  let k=-1; for(let i=0;i<PHR.length;i++) if(t >= W[PHR[i][0]].s - 1/FPS) k=i;\n  if(k<0){cap.innerHTML='';return}\n  const ph=PHR[k];\n  if(cap.dataset.k!=k){ cap.dataset.k=k; cap.innerHTML=ph.map(i=>`<span class=\"w\">${W[i].w.replace(/^(\\d)/,'$1')}</span>`).join(''); }\n  [...cap.children].forEach((sp,j)=>{ const s=W[ph[j]].s-1/FPS; if(t<s){sp.style.opacity=0;return}\n    const p=eo(clamp((t-s)/0.12)); sp.style.opacity=0.4+0.6*p; sp.style.transform=`translateY(${11*(1-p)}px)`; });\n}\n// ===== scene seek =====\nfunction seek(t){\n  const sc = t < CFG.s1End ? 's1' : (t < CFG.s2End ? 's2' : 's3');\n  document.getElementById('s1').style.display = sc==='s1'?'block':'none';\n  document.getElementById('s3').style.display = sc==='s3'?'block':'none';\n  if(sc==='s3') for(const e of ELS) seekEl(e,t);\n  if(CFG.endT!=null){ const h=document.getElementById('cardhdr'); h.style.opacity = 1-clamp((t-CFG.endT)/0.25); }\n  if(sc==='s1') QW.forEach((q,k)=>{ const w=WORDS[k]; const p=w? eo(clamp((t-(w.s-1/FPS))/0.12)) : 0; q.style.color=`rgba(43,47,58,${0.22+0.78*p})`; });\n  seekCap(t, sc==='s2' ? 'none' : sc);\n}\nwindow.__ready = () => { build(); return PHR.map(p=>p.map(i=>WORDS[i].w).join(' ')); };\nwindow.seek = seek;\n";
